package com.acme.reporting;

import io.quarkus.qute.Engine;
import io.quarkus.qute.Template;
import io.quarkus.qute.TemplateInstance;
import io.quarkus.amazon.lambda.http.model.AwsProxyRequest;
import io.quarkus.amazon.lambda.http.model.AwsProxyResponse;

import javax.inject.Inject;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

@Path("/api/reports")
public class ReportGeneratorHandler {

    @Inject
    Engine quteEngine;

    // Allowlist for "safe" template variables - but doesn't prevent injection in template body
    private static final Pattern SAFE_VARIABLE_PATTERN = Pattern.compile("^[a-zA-Z0-9_.]+$");

    @POST
    @Path("/generate")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.TEXT_HTML)
    public AwsProxyResponse generateReport(ReportRequest request) {
        AwsProxyResponse response = new AwsProxyResponse();

        try {
            // Validate report title contains no special chars (misleading security check)
            if (request.getTitle() != null && request.getTitle().length() > 200) {
                response.setStatusCode(400);
                response.setBody("Title too long");
                return response;
            }

            // Build template dynamically from user-provided layout
            String templateContent = buildTemplate(request);

            // Parse and render the template with user data
            Template template = quteEngine.parse(templateContent);

            Map<String, Object> data = new HashMap<>();
            data.put("title", request.getTitle());
            data.put("author", request.getAuthor());
            data.put("generatedAt", java.time.LocalDateTime.now().toString());

            TemplateInstance instance = template.data(data);
            String rendered = instance.render();

            response.setStatusCode(200);
            response.setBody(rendered);
            response.setHeaders(Map.of("Content-Type", "text/html"));

        } catch (Exception e) {
            response.setStatusCode(500);
            response.setBody("Report generation failed: " + e.getMessage());
        }

        return response;
    }

    private String buildTemplate(ReportRequest request) {
        // User controls the headerHtml which is directly interpolated into template source
        // This is the SSTI vector - user content becomes part of the Qute template
        StringBuilder sb = new StringBuilder();
        sb.append("<!DOCTYPE html><html><head><title>{title}</title></head><body>");
        sb.append("<header>");

        // Dangerous: user-supplied headerHtml is treated as template source, not data
        if (request.getHeaderHtml() != null) {
            sb.append(request.getHeaderHtml());
        } else {
            sb.append("<h1>{title}</h1>");
        }

        sb.append("</header>");
        sb.append("<main><p>Report by {author} generated at {generatedAt}</p>");
        sb.append("<div class='content'>{title}</div>");
        sb.append("</main></body></html>");

        return sb.toString();
    }

    public static class ReportRequest {
        private String title;
        private String author;
        private String headerHtml;

        public String getTitle() { return title; }
        public void setTitle(String title) { this.title = title; }
        public String getAuthor() { return author; }
        public void setAuthor(String author) { this.author = author; }
        public String getHeaderHtml() { return headerHtml; }
        public void setHeaderHtml(String headerHtml) { this.headerHtml = headerHtml; }
    }
}
